test("GGF frame rules calculate each side per individual frame and multiply physical quantity",()=>{const normal=calculateFrameFixingPositions({widthMm:1200,heightMm:1400,quantity:2,frameMaterial:"Timber",rule:timber});assert.equal(normal.leftJambFixingCount,3);assert.equal(normal.rightJambFixingCount,3);assert.equal(normal.headFixingCount,0);assert.equal(normal.sillFixingCount,0);assert.equal(normal.totalFixingPositionsPerFrame,6);assert.equal(normal.totalFixingPositions,12);for(const side of [normal.positionsMm.leftJamb,normal.positionsMm.rightJamb]){assert.ok(side[0]>=150&&side[0]<=250);for(let i=1;i<side.length;i++)assert.ok(side[i]-side[i-1]<=600)}const wide=calculateFrameFixingPositions({widthMm:1801,heightMm:1400,quantity:1,frameMaterial:"Timber",rule:timber});assert.equal(wide.headFixingCount,1);assert.equal(wide.sillFixingCount,1);const alu=calculateFrameFixingPositions({widthMm:2000,heightMm:1400,quantity:1,frameMaterial:"Aluminium",rule:aluminium});assert.equal(alu.headFixingCount,4);assert.equal(alu.sillFixingCount,4);assert.equal(alu.source.printedPage,25)});

