test("supplier installation is an explicit persisted substitute and never an Extra",async t=>{
  const root=await mkdtemp(path.join(os.tmpdir(),"qs-supplier-installation-")),db=await open({filename:path.join(root,"test.db"),driver:sqlite3.Database});
  t.after(async()=>{await db.close();await rm(root,{recursive:true,force:true})});
  await seedInstallationCatalogueRebindFixture(db);
  const service=createProjectCalculatorLabService(db,{exchangeRateProvider:async()=>({rawRate:"1",provider:"test",quotedAt:"now"})});
  const initial=await service.getScenario("installation-catalogue-rebind"),initialCommercial=deriveProjectCostingCommercialResult(initial as any),row=initial.supplierCosts.find((item:any)=>item.category==="supplier_installation"),surveyRow=initial.supplierCosts.find((item:any)=>item.category==="supplier_survey");
  assert.deepEqual([row.persistedCategory,row.category,row.includedInCurrentEstimate,row.markupPercent],["other","supplier_installation",false,"0"]);
  assert.equal(surveyRow.markupPercent,"12");
  assert.deepEqual(initialCommercial.extras.map((item:any)=>item.label),["External Aluminium Cills"]);
  assert.equal(initialCommercial.selectedSupplierInstallation.length,0);
  assert.equal(initialCommercial.installationGbp,"4450.00");

  const selected=await service.updateSupplierCost(initial.id,row.id,{includedInCurrentEstimate:true}),selectedCommercial=deriveProjectCostingCommercialResult(selected as any);
  assert.deepEqual(selectedCommercial.extras.map((item:any)=>item.label),["External Aluminium Cills"]);
  assert.equal(selectedCommercial.selectedSupplierInstallation.length,1);
  assert.equal(selectedCommercial.installationGbp,"10939.15");
  assert.equal(selectedCommercial.installationSale,"10939.15");
  assert.equal(selectedCommercial.extrasGbp,"2245.47");
  assert.equal(selected.revisionNumber,2);
  assert.equal(selected.revisions[0].reason,"supplier_installation_selection_reviewed");
  assert.equal((await service.getScenario(initial.id)).supplierCosts.find((item:any)=>item.id===row.id).includedInCurrentEstimate,true);

  const restored=await service.updateSupplierCost(initial.id,row.id,{includedInCurrentEstimate:false}),restoredCommercial=deriveProjectCostingCommercialResult(restored as any);
  assert.equal(restoredCommercial.selectedSupplierInstallation.length,0);
  assert.equal(restoredCommercial.installationGbp,"4450.00");
  assert.equal(restored.revisionNumber,3);
  const reloaded=await service.getScenario(initial.id),reloadedCommercial=deriveProjectCostingCommercialResult(reloaded as any);
  assert.equal(reloaded.supplierCosts.find((item:any)=>item.id===row.id).includedInCurrentEstimate,false);
  assert.equal(reloadedCommercial.installationGbp,"4450.00");
  const persisted=await db.get("SELECT included_in_current_estimate,inclusion_evidence FROM project_calculator_estimate_supplier_costs WHERE id=?",row.id);
  assert.deepEqual([persisted.included_in_current_estimate,persisted.inclusion_evidence],[0,"supplier_installation:user_declined"]);
});

test("supplier installation selection is exclusive and rolls back atomically when revision persistence fails",async t=>{
  const root=await mkdtemp(path.join(os.tmpdir(),"qs-supplier-installation-atomic-")),db=await open({filename:path.join(root,"test.db"),driver:sqlite3.Database});
  t.after(async()=>{await db.close();await rm(root,{recursive:true,force:true})});
  await seedInstallationCatalogueRebindFixture(db);
  await db.run(`INSERT INTO supplier_quote_extras(id,estimate_id,revision_id,category,label,original_text,total_price_amount,currency,trace_json,created_at,included_in_supplier_total)
    SELECT 'installation-fixture-extra-second',estimate_id,revision_id,category,'Installation by Dealer Two','Installation by Dealer Two','12000.00',currency,trace_json,created_at,1
    FROM supplier_quote_extras WHERE id='installation-fixture-extra'`);
  await db.run(`INSERT INTO project_calculator_estimate_supplier_costs(id,scenario_id,source_extra_id,source_attachment_id,source_revision_id,source_snapshot_json,category,label,amount,currency,included_in_current_estimate,inclusion_evidence,created_at)
    SELECT 'installation-fixture-cost-second',scenario_id,'installation-fixture-extra-second',source_attachment_id,source_revision_id,replace(source_snapshot_json,'EcoHaus','Dealer Two'),category,'Installation by Dealer Two','12000.00',currency,0,'supplier_installation:user_declined',created_at
    FROM project_calculator_estimate_supplier_costs WHERE id='installation-fixture-cost'`);
  const service=createProjectCalculatorLabService(db,{exchangeRateProvider:async()=>({rawRate:"1",provider:"test",quotedAt:"now"})});
  await service.updateSupplierCost("installation-catalogue-rebind","installation-fixture-cost",{includedInCurrentEstimate:true});
  const switched=await service.updateSupplierCost("installation-catalogue-rebind","installation-fixture-cost-second",{includedInCurrentEstimate:true});
  assert.deepEqual(switched.supplierCosts.filter((item:any)=>item.category==="supplier_installation").map((item:any)=>[item.id,item.includedInCurrentEstimate]).sort(),[["installation-fixture-cost",false],["installation-fixture-cost-second",true]]);
  await db.exec(`CREATE TRIGGER reject_supplier_installation_revision BEFORE INSERT ON project_calculator_lab_revisions WHEN NEW.reason='supplier_installation_selection_reviewed' BEGIN SELECT RAISE(ABORT,'injected supplier installation revision failure'); END;`);
  await assert.rejects(()=>service.updateSupplierCost("installation-catalogue-rebind","installation-fixture-cost",{includedInCurrentEstimate:true}),/injected supplier installation revision failure/);
  const persisted=await db.all("SELECT id,included_in_current_estimate,inclusion_evidence FROM project_calculator_estimate_supplier_costs WHERE scenario_id=? AND id IN ('installation-fixture-cost','installation-fixture-cost-second') ORDER BY id","installation-catalogue-rebind");
  assert.deepEqual(persisted.map((item:any)=>[item.id,item.included_in_current_estimate,item.inclusion_evidence]),[["installation-fixture-cost",0,"supplier_installation:user_declined"],["installation-fixture-cost-second",1,"supplier_installation:user_selected"]]);
});

