test("Products list price remains source-faithful until the supplier discount is explicitly applied",()=>{const product={id:"position",sourceRevisionId:"revision",classification:"standard",includedInCurrentEstimate:true,quantity:1,originalAmount:"84367.41",gbpAmount:"84367.41",commercialGbpAmount:"84367.41",markupOverridePercent:null},coupler={id:"coupler",sourceRevisionId:"revision",category:"product_supply",includedInCurrentEstimate:true,originalAmount:"37.14",gbpAmount:"37.14",commercialGbpAmount:"37.14"},adjustment={supplierName:"EcoHaus",sourceRevisionId:"revision",quotationReference:"20260057",currency:"GBP",status:"available_not_applied",reasons:[],grossPositionAmount:"84367.41",embeddedAccessoryGrossAmount:"37.14",grossListAmount:"84404.55",discountPercentage:"20",discountAmount:"16880.91",netProductSubtotal:"67523.64",netProductPurchaseGbp:"67523.64",netProductCommercialGbp:"67523.64",purchaseDiscountGbp:"16880.91",commercialDiscountGbp:"16880.91"},scenario:any={id:"test",currency:"GBP",products:[product],supplierCosts:[coupler],supplierProductCommercialAdjustments:[adjustment],packageItems:[],unpricedSupplierTotals:[],supplierPackageUplifts:[],markups:{product:"0",extras:"0",transport:"0",siteVisit:"0",equipment:"0",installation:"0",materials:"0",duties:"0"},options:null,customerPricing:{discount:{mode:"percentage",percentage:"0",amount:"0"},fixedSellingPrice:{enabled:false,amount:"0",currency:"GBP",basis:"ex_vat"}}};const before=deriveProjectCostingCommercialResult(scenario);assert.equal(before.grossBaseProductGbp,"84404.55");assert.equal(before.productGbp,"84404.55");const after=deriveProjectCostingCommercialResult({...scenario,supplierProductCommercialAdjustments:[{...adjustment,status:"applied"}]});assert.equal(after.productGbp,"67523.64");assert.equal(product.originalAmount,"84367.41");assert.equal(coupler.originalAmount,"37.14")});
